      state.algebraRect = pr;
      ctx.save();
      roundRect(ctx, pr.x, pr.y, pr.w, pr.h, 7);
      ctx.fillStyle = 'rgba(255,255,255,0.94)';
      ctx.fill();
      ctx.strokeStyle = '#cfd4da';
      ctx.lineWidth = 1;
      ctx.stroke();
      ctx.fillStyle = '#111111';
      ctx.font = smallFont + 'px Georgia, serif';
      ctx.textAlign = 'left';
      ctx.textBaseline = 'top';
      ctx.fillText('f(x) = ((x − 1)(x + 1)) / ((x − 3)(x + 1))', pr.x + 8, pr.y + 9);
      ctx.fillStyle = red;
      ctx.fillText('cancel common factor x + 1', pr.x + 8, pr.y + smallFont * 2.7);
      ctx.strokeStyle = red;
      ctx.lineWidth = Math.max(1.5, dim * 0.0045);
      ctx.beginPath();
      ctx.moveTo(pr.x + smallFont * 7.1, pr.y + smallFont * 1.65);
      ctx.lineTo(pr.x + smallFont * 10.3, pr.y + smallFont * 0.6);
      ctx.moveTo(pr.x + smallFont * 13.7, pr.y + smallFont * 1.65);
      ctx.lineTo(pr.x + smallFont * 16.9, pr.y + smallFont * 0.6);
      ctx.stroke();
      ctx.fillStyle = '#111111';
      ctx.fillText('= (x − 1) / (x − 3),  x ≠ −1 and x ≠ 3', pr.x + 8, pr.y + smallFont * 5.0);
      ctx.restore();
    } else {
      state.algebraRect = null;
    }

    drawTrace(ctx, chart, smallFont, ah);
    ctx.restore();
  }
};

function drawTrace(ctx, chart, smallFont, ah) {
  if (!state.showTrace) {
    state.tracePixel = null;
    return;
  }
  var ca = chart.chartArea, xs = chart.scales.x, ys = chart.scales.y;
  var x = state.traceX;
  state.tracePixel = null;
  ctx.save();
  if (Math.abs(x - 3) < 1e-9) {
    drawLabelBox(ctx, ['x = 3', 'undefined'], xs.getPixelForValue(3) + 10, ca.top + 18, smallFont + 'px sans-serif', red, 'left');
    ctx.restore();
    return;
  }
  var y = f(x);
  var px = xs.getPixelForValue(x);
  var pyRaw = ys.getPixelForValue(y);
  var py = Math.max(ca.top + 6, Math.min(ca.bottom - 6, pyRaw));
  state.tracePixel = { x: px, y: py };
  ctx.fillStyle = gold;
  ctx.strokeStyle = axisBlack;
  ctx.lineWidth = Math.max(1, Math.min(1.5, Math.min(ca.width, ca.height) * 0.004));
  ctx.beginPath();
  ctx.arc(px, py, Math.max(3.5, Math.min(7, Math.min(ca.width, ca.height) * 0.014)), 0, Math.PI * 2);
  ctx.fill();
  ctx.stroke();

  var off = py !== pyRaw;
  var labelLines = ['x = ' + x.toFixed(2), (off ? 'y ≈ ' : 'y = ') + y.toFixed(2) + (off ? ' (off scale)' : '')];
  var lx = x < 3 ? px - 118 : px + 12;
  if (lx < ca.left + 5) lx = ca.left + 5;
  if (lx > ca.right - 130) lx = ca.right - 130;
  var ly = py + (py < (ca.top + ca.bottom) / 2 ? 10 : -42);
  ly = Math.max(ca.top + 5, Math.min(ca.bottom - 46, ly));
  drawLabelBox(ctx, labelLines, lx, ly, smallFont + 'px sans-serif', '#111111', 'left');
  ctx.restore();
}

var chart = new Chart(canvas, {
  type: 'line',
  data: {
    datasets: [
      {
        data: sample(-3.9, 2.94, 300),
        parsing: false,
        borderColor: teal,
        borderWidth: 3,
        pointRadius: 0,
        tension: 0,
        clip: false
      },
      {
        data: sample(3.16, 9.6, 300),
        parsing: false,
        borderColor: teal,
        borderWidth: 3,
        pointRadius: 0,
        tension: 0,
        clip: false
      }
    ]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: { duration: 0 },
    layout: { padding: { left: 132, right: 62, top: 28, bottom: 74 } },
    plugins: { legend: { display: false }, tooltip: { enabled: false } },
    scales: {
      x: { type: 'linear', min: -4.5, max: 10.5, display: false },
      y: { type: 'linear', min: -6.7, max: 7, display: false }
    },
