});
window.__markRendered();

function refreshChart() {
  var curveWidth = state.highlightActive && state.highlightBreak === 'Vertical asymptote' ? 3.2 : 3;
  chart.data.datasets[0].borderWidth = curveWidth;
  chart.data.datasets[1].borderWidth = curveWidth;
  chart.update('none');
}

function toggle_highlightBreak(on) {
  state.highlightActive = true;
  state.highlightBreak = on ? 'Vertical asymptote' : 'Removable discontinuity';
  var out = document.getElementById('highlightBreakVal');
  if (out) out.value = state.highlightBreak;
  refreshChart();
}

function update_approachAsymptote(v) {
  state.traceX = v;
  state.showTrace = true;
  var out = document.getElementById('approachAsymptoteVal');
  if (out) out.value = v.toFixed(2);
  refreshChart();
}

function toggle_factorCancelledView(on) {
  state.factorView = on ? 'Show cancellation' : 'Graph only';
  var out = document.getElementById('factorCancelledViewVal');
  if (out) out.value = state.factorView;
  refreshChart();
}

var steps = [
  {
    title: 'Find the removable hole',
    narration: 'The hollow circle at x = -1 marks a point that is missing from the graph. The nearby curve behaves normally on both sides, so this break is only one absent function value.',
    state: { highlightBreak: 'Removable discontinuity', approachAsymptote: 2.5, factorCancelledView: 'Graph only' }
  },
  {
    title: 'Reveal why the hole occurs',
    narration: 'The common factor x + 1 cancels algebraically, leaving the same curve shape but preserving the restriction x ≠ -1. That is why the graph has a hole rather than a vertical blow-up at x = -1.',
    state: { highlightBreak: 'Removable discontinuity', approachAsymptote: 2.5, factorCancelledView: 'Show cancellation' }
  },
  {
    title: 'Contrast the vertical asymptote',
    narration: 'At x = 3, the dashed red line is not a missing point. Moving the trace point toward x = 3 shows the curve plunging downward on the left and rising upward on the right.',
    state: { highlightBreak: 'Vertical asymptote', approachAsymptote: 2.9, factorCancelledView: 'Show cancellation' }
  },
  {
    title: 'Approach from the right',
    narration: 'Just to the right of x = 3, the graph is extremely high and then falls back toward its long-run level near y = 1. This unbounded behavior is what makes x = 3 a vertical asymptote.',
    state: { highlightBreak: 'Vertical asymptote', approachAsymptote: 3.1, factorCancelledView: 'Show cancellation' }
  }
];

function applyStep(i) {
  state.step = Math.max(0, Math.min(steps.length - 1, i));
  var st = steps[state.step].state;
  var h = document.getElementById('highlightBreakInput');
  var a = document.getElementById('approachAsymptoteInput');
  var fc = document.getElementById('factorCancelledViewInput');

  if (h) h.checked = st.highlightBreak === 'Vertical asymptote';
  if (a) a.value = st.approachAsymptote;
  if (fc) fc.checked = st.factorCancelledView === 'Show cancellation';

  state.highlightBreak = st.highlightBreak;
  state.highlightActive = state.step > 0;
  state.traceX = st.approachAsymptote;
  state.showTrace = state.step >= 2;
  state.factorView = st.factorCancelledView;

  document.getElementById('highlightBreakVal').value = state.highlightBreak;
  document.getElementById('approachAsymptoteVal').value = state.traceX.toFixed(2);
  document.getElementById('factorCancelledViewVal').value = state.factorView;
  document.getElementById('demoNarration').textContent = steps[state.step].narration;
  document.getElementById('stepLabel').textContent = (state.step + 1) + ' / ' + steps.length;
  refreshChart();
}

function prevStep() {
  applyStep(state.step - 1);
}

function nextStep() {
  applyStep(state.step + 1);
}

function hitFeature(evt) {
  var rect = canvas.getBoundingClientRect();
  var mx = evt.clientX - rect.left, my = evt.clientY - rect.top;
  var xs = chart.scales.x, ys = chart.scales.y, ca = chart.chartArea;
  var hx = xs.getPixelForValue(-1), hy = ys.getPixelForValue(0.5);
  var x3 = xs.getPixelForValue(3);
  var dHole = Math.hypot(mx - hx, my - hy);
  if (dHole < 14) return 'hole';
  if (Math.abs(mx - x3) < 9 && my > ca.top && my < ca.bottom) return 'asymptote';
  if (state.tracePixel && Math.hypot(mx - state.tracePixel.x, my - state.tracePixel.y) < 15) return 'trace';
  if (state.algebraRect && mx >= state.algebraRect.x && mx <= state.algebraRect.x + state.algebraRect.w && my >= state.algebraRect.y && my <= state.algebraRect.y + state.algebraRect.h) return 'algebra';
  return null;
}

canvas.addEventListener('mousemove', function (e) {
  var hit = hitFeature(e);
  canvas.style.cursor = hit ? 'pointer' : 'default';
  if (hit === 'hole') showTooltip('A cancelled factor leaves this single missing point at x = −1.', e);
  else if (hit === 'asymptote') showTooltip('The uncancelled denominator is zero at x = 3, so values become unbounded.', e);
  else if (hit === 'trace') showTooltip('Drag the slider to compare finite values with blow-up near x = 3.', e);
  else if (hit === 'algebra') showTooltip('The factor x + 1 cancels, but the original restriction x ≠ −1 remains.', e);
  else hideTooltip();
});
canvas.addEventListener('mouseleave', hideTooltip);
canvas.addEventListener('click', function (e) {
  var hit = hitFeature(e);
  if (hit === 'hole') showPopup('Removable discontinuity', 'The graph follows the simplified curve on both sides of x = −1, but the original formula is undefined there. Filling in just one point would repair this break.');
  if (hit === 'asymptote') showPopup('Vertical asymptote', 'At x = 3, the denominator has an uncancelled zero. Function values grow without bound, so no single filled-in point can repair the graph.');
  if (hit === 'trace') showPopup('Trace point', 'The trace point evaluates f(x) = (x − 1)/(x − 3). As x approaches 3, the denominator approaches 0 while the numerator does not, making the y-value extremely large in magnitude.');
  if (hit === 'algebra') showPopup('Algebraic cause', 'The common factor x + 1 cancels, creating the simplified curve. The cancellation explains the hole at x = −1, while x = 3 remains an uncancelled denominator zero.');
});

applyStep(0);
